107:   const rewrittenLines = lines.map(line => {
108:     const trimmed = line.trim();
109:     if (!trimmed) return line;
110: 
111:     // 1. Process tags with URI="..." or X-ASSET-URI="..." attributes
112:     if (trimmed.startsWith('#EXT-X-MEDIA:') ||
113:         trimmed.startsWith('#EXT-X-MAP:') ||
114:         trimmed.startsWith('#EXT-X-KEY:') ||
115:         trimmed.startsWith('#EXT-X-I-FRAME-STREAM-INF:') ||
116:         trimmed.startsWith('#EXT-X-PRELOAD-HINT:') ||
117:         trimmed.startsWith('#EXT-X-RENDITION-REPORT:') ||
118:         trimmed.startsWith('#EXT-X-DATERANGE:')) {
119:       return line.replace(/\b([A-Z0-9-]*URI)=(["'])(.*?)\2/g, (match, attrName, quote, rawUri) => {
120:         const absolute = resolveUrl(rawUri, baseUrl);
121:         const proxied = `${proxyPrefix}${encodeURIComponent(unwrapProxyUrl(absolute))}`;
122:         return `${attrName}="${proxied}"`;
123:       });
124:     }
125: 
126:     // 2. Preserve non-URI tags and comments
127:     if (trimmed.startsWith('#')) {
128:       return line;
129:     }
130: 
131:     // 3. Process standalone segment or variant playlist URI lines
132:     const absolute = resolveUrl(trimmed, baseUrl);
133:     return `${proxyPrefix}${encodeURIComponent(unwrapProxyUrl(absolute))}`;
134:   });
135: 
136:   return rewrittenLines.join('\n');
