/**
 * cinejoy-webos Local Streaming Proxy Daemon
 * Port: 8088 (auto-fallback if occupied)
 * Dependencies: Native Node.js built-ins only (http, url, fs, path, stream)
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const { URL } = require('url');

// Sibling engine modules (M1.1 and M1.2)
const resolver = require('./resolver');
const hlsProxy = require('./hls-proxy');

const DEFAULT_PORT = parseInt(process.env.PORT, 10) || 8088;
const DEFAULT_HOST = process.env.HOST || '127.0.0.1';
const MAX_PORT_ATTEMPTS = 10;
const STATUS_FILE = path.join(__dirname, '.server-port');
const STATUS_JSON_FILE = path.join(__dirname, '.status.json');

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': '*',
  'Access-Control-Expose-Headers': 'Content-Length, Content-Range, Content-Type, Accept-Ranges',
  'Access-Control-Max-Age': '86400',
};

let activeServer = null;
let activePort = DEFAULT_PORT;

/**
 * Standardized JSON response helper
 */
function sendJson(res, statusCode, data) {
  const payload = Buffer.from(JSON.stringify(data), 'utf8');
  res.writeHead(statusCode, {
    ...CORS_HEADERS,
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': payload.length,
  });
  res.end(payload);
}

/**
 * Standardized error response helper
 */
function sendError(res, statusCode, message, details = null) {
  const body = { error: message, statusCode };
  if (details) body.details = details;
  sendJson(res, statusCode, body);
}

/**
 * Converts SubRip (.srt) subtitles to WebVTT (.vtt) format
 */
function convertSrtToVtt(srtText) {
  if (srtText.trim().startsWith('WEBVTT')) {
    return srtText;
  }
  // Replace comma in timestamps: 00:00:20,000 --> 00:00:24,400 to 00:00:20.000 --> 00:00:24.400
  const normalized = srtText.replace(
    /(\d{2}:\d{2}:\d{2}),(\d{3})/g,
    '$1.$2'
  );
  return `WEBVTT\n\n${normalized.trim()}\n`;
}

/**
 * Main HTTP Request Dispatcher
 */
async function requestHandler(req, res) {
  // 1. Handle CORS Preflight OPTIONS
  if (req.method === 'OPTIONS') {
    res.writeHead(204, {
      ...CORS_HEADERS,
      'Content-Length': 0,
    });
    return res.end();
  }

  // Parse URL safely
  let parsedUrl;
  try {
    parsedUrl = new URL(req.url, `http://${req.headers.host || '127.0.0.1'}`);
  } catch (err) {
    return sendError(res, 400, 'Invalid Request URL');
  }

  const { pathname, searchParams } = parsedUrl;

  try {
    // 2. Route: GET /health or /api/health
    if (pathname === '/health' || pathname === '/api/health') {
      return sendJson(res, 200, {
        status: 'ok',
        uptime: process.uptime(),
        port: activePort,
        version: '1.0.0',
        timestamp: new Date().toISOString(),
      });
    }

    // 3. Route: GET /api/servers
    if (pathname === '/api/servers') {
      try {
        const serverData = await resolver.getServers();
        return sendJson(res, 200, serverData);
      } catch (err) {
        // Fallback cluster servers if remote listing fails
        return sendJson(res, 200, {
          servers: [
            { name: 'secret', '4k': true, status: 'ok' },
            { name: 'Nebula', '4k': false, status: 'ok' },
            { name: 'Lisbon', '4k': true, status: 'ok' },
            { name: 'Solara', '4k': false, status: 'ok' },
            { name: 'Athens', '4k': false, status: 'ok' },
          ],
        });
      }
    }

    // 4. Route: GET /api/stream
    if (pathname === '/api/stream') {
      const tmdbId = searchParams.get('tmdbId');
      const type = searchParams.get('type');
      const season = searchParams.get('season');
      const episode = searchParams.get('episode');
      const server = searchParams.get('server') || 'secret';

      if (!tmdbId || !type) {
        return sendError(res, 400, 'Missing required query parameters: tmdbId and type are required');
      }

      if (type !== 'movie' && type !== 'tv') {
        return sendError(res, 400, "Invalid type parameter: must be 'movie' or 'tv'");
      }

      if (type === 'tv' && (!season || !episode)) {
        return sendError(res, 400, "Missing required query parameters: season and episode are required for type 'tv'");
      }

      const streamResult = await resolver.resolveStream({
        tmdbId,
        type,
        season,
        episode,
        server,
      });

      if (!streamResult || !streamResult.playlist) {
        return sendError(res, 502, 'Stream resolution failed: no playlist found');
      }

      // Construct local proxy stream URL
      const host = req.headers.host || `127.0.0.1:${activePort}`;
      const encodedPlaylist = encodeURIComponent(streamResult.playlist);
      const streamUrl = `http://${host}/hls/proxy?url=${encodedPlaylist}`;

      // Build subtitles array
      const subtitles = [];
      if (Array.isArray(streamResult.captions)) {
        for (const cap of streamResult.captions) {
          subtitles.push({
            label: cap.language || cap.id || 'English',
            srclang: cap.id || 'en',
            src: `http://${host}/proxy/sub?url=${encodeURIComponent(cap.url)}`,
          });
        }
      }

      // Query external subtitles from subs.wing.st
      try {
        const extSubs = await resolver.fetchSubtitles({ tmdbId, type, season, episode });
        if (Array.isArray(extSubs)) {
          for (const s of extSubs) {
            if (s.url && !subtitles.some(existing => existing.src.includes(encodeURIComponent(s.url)))) {
              subtitles.push({
                label: s.display || s.language || 'External',
                srclang: s.language || 'en',
                src: `http://${host}/proxy/sub?url=${encodeURIComponent(s.url)}`,
              });
            }
          }
        }
      } catch (_) {
        // External subtitles failure is non-fatal
      }

      return sendJson(res, 200, {
        success: true,
        streamUrl,
        originalUrl: streamResult.playlist,
        server: streamResult.server || server,
        subtitles,
      });
    }

    // 5. Route: GET /hls/proxy
    if (pathname === '/hls/proxy') {
      const targetUrl = searchParams.get('url');
      if (!targetUrl) {
        return sendError(res, 400, "Missing 'url' query parameter for HLS proxy");
      }
      return hlsProxy.handleHlsProxy(req, res, targetUrl, activePort);
    }

    // 6. Route: GET /proxy/sub
    if (pathname === '/proxy/sub') {
      const subUrl = searchParams.get('url');
      if (!subUrl) {
        return sendError(res, 400, "Missing 'url' query parameter for subtitle proxy");
      }

      try {
        const subResponse = await fetch(subUrl, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 Chrome/108.0.5359.211',
            'Origin': 'https://cinejoy.pk',
            'Referer': 'https://cinejoy.pk/',
          },
          signal: AbortSignal.timeout(10000)
        });

        if (!subResponse.ok) {
          return sendError(res, 502, `Failed to fetch remote subtitle: ${subResponse.status} ${subResponse.statusText}`);
        }

        const rawText = await subResponse.text();
        const vttContent = convertSrtToVtt(rawText);
        const buffer = Buffer.from(vttContent, 'utf8');

        res.writeHead(200, {
          ...CORS_HEADERS,
          'Content-Type': 'text/vtt; charset=utf-8',
          'Content-Length': buffer.length,
        });
        return res.end(buffer);
      } catch (err) {
        return sendError(res, 502, 'Failed to fetch subtitle', err.message);
      }
    }

    // 7. Route: 404 Fallthrough
    return sendError(res, 404, 'Endpoint Not Found', { path: pathname });
  } catch (err) {
    console.error(`[cinejoy-server] Error handling ${req.method} ${pathname}:`, err);
    return sendError(res, 500, 'Internal Server Error', err.message);
  }
}

/**
 * Writes active port and metadata to status files
 */
function writeStatusFiles(port) {
  try {
    fs.writeFileSync(STATUS_FILE, port.toString(), 'utf8');
    const statusMeta = {
      port,
      host: DEFAULT_HOST,
      pid: process.pid,
      startedAt: new Date().toISOString(),
      version: '1.0.0',
    };
    fs.writeFileSync(STATUS_JSON_FILE, JSON.stringify(statusMeta, null, 2), 'utf8');
  } catch (err) {
    console.warn('[cinejoy-server] Warning: Could not write status file:', err.message);
  }
}

/**
 * Removes status files upon shutdown
 */
function removeStatusFiles() {
  try {
    if (fs.existsSync(STATUS_FILE)) fs.unlinkSync(STATUS_FILE);
    if (fs.existsSync(STATUS_JSON_FILE)) fs.unlinkSync(STATUS_JSON_FILE);
  } catch (_) {}
}

/**
 * Starts the HTTP server with port collision detection and fallback
 */
function startServer(initialPort = DEFAULT_PORT, host = DEFAULT_HOST) {
  return new Promise((resolve, reject) => {
    let currentPort = initialPort;
    let attempts = 0;

    function tryListen() {
      const server = http.createServer(requestHandler);

      server.on('error', (err) => {
        if (err.code === 'EADDRINUSE') {
          attempts++;
          console.warn(`[cinejoy-server] Port ${currentPort} in use, trying ${currentPort + 1}...`);
          currentPort++;
          if (attempts >= MAX_PORT_ATTEMPTS) {
            return reject(new Error(`Could not bind to any port in range ${initialPort}-${currentPort - 1}`));
          }
          setTimeout(tryListen, 50);
        } else {
          reject(err);
        }
      });

      server.on('listening', () => {
        activeServer = server;
        activePort = currentPort;
        writeStatusFiles(activePort);
        console.log(`[cinejoy-server] Server running on http://${host}:${activePort} (PID: ${process.pid})`);
        resolve({ server, port: activePort });
      });

      server.listen(currentPort, host);
    }

    tryListen();
  });
}

/**
 * Stops the active HTTP server cleanly
 */
function stopServer() {
  return new Promise((resolve) => {
    removeStatusFiles();
    if (activeServer) {
      if (typeof activeServer.closeAllConnections === 'function') {
        activeServer.closeAllConnections();
      }
      activeServer.close(() => {
        activeServer = null;
        resolve();
      });
    } else {
      resolve();
    }
  });
}

/**
 * Returns current active port
 */
function getActivePort() {
  return activePort;
}

// Clean exit handlers
process.on('SIGTERM', async () => {
  console.log('[cinejoy-server] Received SIGTERM, shutting down...');
  await stopServer();
  process.exit(0);
});

process.on('SIGINT', async () => {
  console.log('[cinejoy-server] Received SIGINT, shutting down...');
  await stopServer();
  process.exit(0);
});

process.on('exit', () => {
  removeStatusFiles();
});

// Auto-run if executed directly as main script
if (require.main === module) {
  startServer().catch((err) => {
    console.error('[cinejoy-server] Fatal startup error:', err);
    process.exit(1);
  });
}

module.exports = {
  startServer,
  stopServer,
  getActivePort,
  requestHandler,
  CORS_HEADERS,
};

/**
 * Milestone 1 Automated Verification Test Suite
 * Validates: server/index.js, server/resolver.js, server/hls-proxy.js
 * Run via: node server/test-m1.js
 */

const http = require('http');
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

const DEFAULT_PORT = 8088;
const TEST_HOST = '127.0.0.1';
let activePort = DEFAULT_PORT;
let serverChildProcess = null;

// ANSI Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m',
};

/**
 * Standard HTTP request helper returning Promise
 */
function request(options, requestBody = null) {
  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        const rawBuffer = Buffer.concat(chunks);
        let text = null;
        let json = null;
        try {
          text = rawBuffer.toString('utf8');
          json = JSON.parse(text);
        } catch (_) {}
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          buffer: rawBuffer,
          text,
          json,
        });
      });
    });

    req.on('error', reject);
    req.setTimeout(15000, () => {
      req.destroy(new Error('Request timed out (15s)'));
    });

    if (requestBody) {
      req.write(requestBody);
    }
    req.end();
  });
}

/**
 * Polls the /health endpoint until the server is ready or timeout expires
 */
async function waitForServer(port, maxWaitMs = 6000) {
  const start = Date.now();
  const statusFile = path.join(__dirname, '.server-port');
  while (Date.now() - start < maxWaitMs) {
    let checkPort = port;
    if (fs.existsSync(statusFile)) {
      try {
        const p = parseInt(fs.readFileSync(statusFile, 'utf8').trim(), 10);
        if (p) checkPort = p;
      } catch (_) {}
    }
    try {
      const res = await request({
        hostname: TEST_HOST,
        port: checkPort,
        path: '/health',
        method: 'GET',
      });
      if (res.statusCode === 200 && res.json && res.json.status === 'ok') {
        activePort = checkPort;
        return true;
      }
    } catch (_) {}
    await new Promise((r) => setTimeout(r, 100));
  }
  return false;
}

/**
 * Test Execution Framework
 */
let totalTests = 0;
let passedTests = 0;
let failedTests = 0;
const testResults = [];

async function runTest(name, testFn) {
  totalTests++;
  const startTime = Date.now();
  process.stdout.write(`  [${totalTests}] ${name} ... `);
  try {
    await testFn();
    const duration = Date.now() - startTime;
    console.log(`${C.green}${C.bold}✔ PASS${C.reset} ${C.gray}(${duration}ms)${C.reset}`);
    passedTests++;
    testResults.push({ name, pass: true, duration });
  } catch (err) {
    const duration = Date.now() - startTime;
    console.log(`${C.red}${C.bold}✖ FAIL${C.reset} ${C.gray}(${duration}ms)${C.reset}`);
    console.error(`      ${C.red}Error: ${err.message}${C.reset}`);
    failedTests++;
    testResults.push({ name, pass: false, error: err.message, duration });
  }
}

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Assertion failed');
  }
}

/**
 * Test Suite Execution
 */
async function main() {
  console.log(`\n${C.bold}${C.cyan}================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}   CINEJOY-WEBOS: MILESTONE 1 VERIFICATION TEST HARNESS        ${C.reset}`);
  console.log(`${C.bold}${C.cyan}================================================================${C.reset}\n`);

  // Phase 1: Server Discovery or Child Spawning
  console.log(`${C.bold}► Phase 1: Environment Initialization${C.reset}`);

  // Check if status file exists
  const statusFile = path.join(__dirname, '.server-port');
  if (fs.existsSync(statusFile)) {
    const content = fs.readFileSync(statusFile, 'utf8').trim();
    if (content) activePort = parseInt(content, 10);
  }

  const isAlreadyRunning = await waitForServer(activePort, 800);
  if (isAlreadyRunning) {
    console.log(`  Connected to running proxy daemon on http://${TEST_HOST}:${activePort}\n`);
  } else {
    console.log(`  Spawning local proxy daemon (node server/index.js)...`);
    serverChildProcess = spawn('node', [path.join(__dirname, 'index.js')], {
      stdio: 'pipe',
      env: { ...process.env, PORT: DEFAULT_PORT.toString() },
    });

    serverChildProcess.stderr.on('data', (d) => {
      // process.stderr.write(d);
    });

    const isReady = await waitForServer(DEFAULT_PORT, 6000);
    assert(isReady, `Server failed to start on port ${DEFAULT_PORT} within 6 seconds`);
    console.log(`  Proxy daemon successfully spawned and responsive on port ${activePort}\n`);
  }

  // Phase 2: Execute Test Suite
  console.log(`${C.bold}► Phase 2: Verification Tests Execution${C.reset}`);

  let resolvedMovieStreamUrl = null;
  let resolvedVariantProxyUrl = null;

  // TC1: /health endpoint
  await runTest('TC1: Liveness Probe (GET /health)', async () => {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/health',
      method: 'GET',
    });
    assert(res.statusCode === 200, `Expected status 200, got ${res.statusCode}`);
    assert(res.json && res.json.status === 'ok', `Expected status: "ok", got ${JSON.stringify(res.json)}`);
    assert(typeof res.json.uptime === 'number' && res.json.uptime >= 0, 'Missing or invalid uptime');
    assert(res.headers['access-control-allow-origin'] === '*', 'Missing Access-Control-Allow-Origin: *');
  });

  // TC2: Global CORS Preflight
  await runTest('TC2: Global CORS Preflight (OPTIONS /api/stream)', async () => {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/stream',
      method: 'OPTIONS',
      headers: {
        Origin: 'http://localhost:3000',
        'Access-Control-Request-Method': 'GET',
      },
    });
    assert(res.statusCode === 204, `Expected status 204, got ${res.statusCode}`);
    assert(res.headers['access-control-allow-origin'] === '*', 'Missing CORS origin wildcard');
    assert(res.headers['access-control-allow-methods'].includes('GET'), 'Missing GET in allowed methods');
  });

  // TC3: Server cluster list
  await runTest('TC3: Server Cluster List (GET /api/servers)', async () => {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/servers',
      method: 'GET',
    });
    assert(res.statusCode === 200, `Expected status 200, got ${res.statusCode}`);
    assert(res.json && Array.isArray(res.json.servers), 'Expected servers array in response');
    assert(res.json.servers.length > 0, 'Servers list is empty');
    const secretServer = res.json.servers.find((s) => s.name === 'secret');
    assert(secretServer !== undefined, "Primary streaming server 'secret' not found in server list");
  });

  // TC4: Movie Stream Resolution (Inception TMDB 27205)
  await runTest('TC4: Movie Stream Resolution (GET /api/stream?tmdbId=27205&type=movie)', async () => {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/stream?tmdbId=27205&type=movie&server=secret',
      method: 'GET',
    });
    assert(res.statusCode === 200, `Expected status 200, got ${res.statusCode} (${res.text})`);
    assert(res.json && res.json.success === true, 'Expected success: true in stream result');
    assert(typeof res.json.streamUrl === 'string', 'streamUrl must be a string');
    assert(
      res.json.streamUrl.startsWith(`http://${TEST_HOST}:${activePort}/hls/proxy?url=`),
      `streamUrl does not point to local proxy: ${res.json.streamUrl}`
    );
    assert(
      res.json.originalUrl && res.json.originalUrl.includes('lightspeed.st'),
      `originalUrl does not target lightspeed.st CDN: ${res.json.originalUrl}`
    );
    resolvedMovieStreamUrl = res.json.streamUrl;
  });

  // TC5: TV Show Stream Resolution (Breaking Bad S01E01 TMDB 1396)
  await runTest('TC5: TV Series Episode Resolution (GET /api/stream?tmdbId=1396&type=tv&season=1&episode=1)', async () => {
    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/stream?tmdbId=1396&type=tv&season=1&episode=1&server=secret',
      method: 'GET',
    });
    assert(res.statusCode === 200, `Expected status 200, got ${res.statusCode}`);
    assert(res.json && res.json.success === true, 'Expected success: true');
    assert(res.json.streamUrl && res.json.streamUrl.includes('/hls/proxy'), 'Invalid streamUrl structure');
  });

  // TC6: Master HLS Playlist Proxy & Rewriting
  await runTest('TC6: Master HLS Playlist Proxy & URL Rewriting', async () => {
    assert(resolvedMovieStreamUrl, 'Skipping: TC4 did not provide a streamUrl');
    const proxyPath = resolvedMovieStreamUrl.replace(`http://${TEST_HOST}:${activePort}`, '');

    const res = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: proxyPath,
      method: 'GET',
    });

    assert(res.statusCode === 200, `Expected status 200, got ${res.statusCode}`);
    assert(res.text && res.text.startsWith('#EXTM3U'), 'Manifest does not start with #EXTM3U');
    assert(res.headers['access-control-allow-origin'] === '*', 'Missing CORS header on manifest');

    // Verify all variant stream lines are rewritten to local proxy
    const lines = res.text.split('\n').map((l) => l.trim()).filter(Boolean);
    const variantUris = lines.filter((l) => !l.startsWith('#'));
    assert(variantUris.length > 0, 'No variant playlists found in master manifest');

    for (const uri of variantUris) {
      assert(
        uri.startsWith(`http://${TEST_HOST}:${activePort}/hls/proxy?url=`),
        `Variant URI not rewritten to local proxy: ${uri}`
      );
    }

    // Save the first variant playlist proxy URL for TC7
    resolvedVariantProxyUrl = variantUris[0];
  });

  // TC7: Variant Manifest & ISO BMFF init.png Segment Magic Bytes
  await runTest('TC7: Variant Manifest & fMP4 init.png Header Verification', async () => {
    assert(resolvedVariantProxyUrl, 'Skipping: TC6 did not provide a variant playlist proxy URL');
    const variantPath = resolvedVariantProxyUrl.replace(`http://${TEST_HOST}:${activePort}`, '');

    const variantRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: variantPath,
      method: 'GET',
    });

    assert(variantRes.statusCode === 200, `Variant manifest returned ${variantRes.statusCode}`);
    assert(variantRes.text.includes('#EXT-X-MAP:URI="'), 'Variant playlist missing #EXT-X-MAP tag');

    // Extract the init segment URL
    const match = variantRes.text.match(/#EXT-X-MAP:URI="([^"]+)"/);
    assert(match && match[1], 'Could not extract init segment URI from variant manifest');
    const initProxyUrl = match[1];
    assert(
      initProxyUrl.startsWith(`http://${TEST_HOST}:${activePort}/hls/proxy?url=`),
      `Init segment URI not rewritten: ${initProxyUrl}`
    );

    // Fetch the init segment through the proxy
    const initPath = initProxyUrl.replace(`http://${TEST_HOST}:${activePort}`, '');
    const initRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: initPath,
      method: 'GET',
    });

    assert(initRes.statusCode === 200, `init.png segment fetch returned ${initRes.statusCode}`);
    assert(initRes.buffer.length >= 16, 'init.png segment buffer too small (<16 bytes)');

    // ISO BMFF verification: Box type at offset 4..8 must be 'ftyp'
    const boxType = initRes.buffer.subarray(4, 8).toString('ascii');
    assert(boxType === 'ftyp', `init.png is not an ISO BMFF segment! Expected 'ftyp' at offset 4, got '${boxType}'`);
  });

  // TC8: Media Fragment Chunk Proxying
  await runTest('TC8: Media Segment Proxying (seg-v0.png)', async () => {
    assert(resolvedVariantProxyUrl, 'Skipping: TC6 did not provide variant playlist');
    const variantPath = resolvedVariantProxyUrl.replace(`http://${TEST_HOST}:${activePort}`, '');

    const variantRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: variantPath,
      method: 'GET',
    });

    const lines = variantRes.text.split('\n').map((l) => l.trim()).filter(Boolean);
    const mediaSegments = lines.filter((l) => !l.startsWith('#'));
    assert(mediaSegments.length > 0, 'No media chunks found in variant playlist');

    const firstSegmentUrl = mediaSegments[0];
    const segmentPath = firstSegmentUrl.replace(`http://${TEST_HOST}:${activePort}`, '');

    const segRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: segmentPath,
      method: 'GET',
      headers: { Range: 'bytes=0-1023' }, // Request first 1KB
    });

    assert(
      segRes.statusCode === 200 || segRes.statusCode === 206,
      `Media segment returned status ${segRes.statusCode}`
    );
    assert(segRes.buffer.length > 0, 'Media segment returned empty buffer');
    assert(segRes.headers['access-control-allow-origin'] === '*', 'Missing CORS on media chunk');
  });

  // TC9: Subtitle Proxying & WebVTT Format
  await runTest('TC9: Subtitle Proxying & Conversion (GET /proxy/sub)', async () => {
    // 1. Test SRT to WebVTT conversion via data URI
    const testSrtDataUrl = `data:text/plain;charset=utf-8,${encodeURIComponent('1\n00:00:01,000 --> 00:00:04,000\nHello from Cinejoy TV\n')}`;
    const srtRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: `/proxy/sub?url=${encodeURIComponent(testSrtDataUrl)}`,
      method: 'GET',
    });

    assert(srtRes.statusCode === 200, `Expected status 200 for SRT conversion, got ${srtRes.statusCode}`);
    assert(srtRes.text && srtRes.text.startsWith('WEBVTT'), 'Subtitle does not start with WEBVTT header');
    assert(srtRes.text.includes('00:00:01.000 --> 00:00:04.000'), 'SRT comma timestamps not converted to dot notation');
    assert(srtRes.headers['access-control-allow-origin'] === '*', 'Missing CORS header on subtitles');

    // 2. Test remote subtitle proxying
    const sampleSubUrl = 'https://subs.wing.st/subtitles?type=movie&tmdb=27205';
    const subRes = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: `/proxy/sub?url=${encodeURIComponent(sampleSubUrl)}`,
      method: 'GET',
    });

    if (subRes.statusCode === 200) {
      assert(subRes.text && subRes.text.startsWith('WEBVTT'), 'Remote subtitle does not start with WEBVTT header');
      assert(subRes.headers['access-control-allow-origin'] === '*', 'Missing CORS header on remote subtitles');
    } else {
      assert(subRes.json && subRes.json.error, 'Sub proxy error response not JSON-formatted');
    }
  });

  // TC10: Boundary & Error Case Handling
  await runTest('TC10: Boundary & Error Handling (400 & 404 responses)', async () => {
    // Missing tmdbId
    const resNoId = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/stream?type=movie',
      method: 'GET',
    });
    assert(resNoId.statusCode === 400, `Expected 400 for missing tmdbId, got ${resNoId.statusCode}`);

    // TV show without season/episode
    const resNoEp = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/stream?tmdbId=1396&type=tv',
      method: 'GET',
    });
    assert(resNoEp.statusCode === 400, `Expected 400 for TV show missing season/episode, got ${resNoEp.statusCode}`);

    // HLS proxy missing url
    const resNoUrl = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/hls/proxy',
      method: 'GET',
    });
    assert(resNoUrl.statusCode === 400, `Expected 400 for missing url in HLS proxy, got ${resNoUrl.statusCode}`);

    // Unknown endpoint
    const res404 = await request({
      hostname: TEST_HOST,
      port: activePort,
      path: '/api/unsupported-endpoint',
      method: 'GET',
    });
    assert(res404.statusCode === 404, `Expected 404 for unknown route, got ${res404.statusCode}`);
    assert(res404.json && res404.json.error === 'Endpoint Not Found', 'Expected structured 404 JSON body');
  });

  // Phase 3: Test Results Summary & Teardown
  console.log(`\n${C.bold}► Phase 3: Test Execution Summary${C.reset}`);
  console.log('----------------------------------------------------------------');
  console.log(`  Total Tests Run:  ${totalTests}`);
  console.log(`  Passed Tests:     ${C.green}${passedTests}${C.reset}`);
  console.log(`  Failed Tests:     ${failedTests > 0 ? `${C.red}${failedTests}` : '0'}${C.reset}`);
  console.log('----------------------------------------------------------------');

  // Clean up child process if spawned
  if (serverChildProcess) {
    console.log('  Terminating spawned child server process...');
    serverChildProcess.kill('SIGTERM');
  }

  if (failedTests > 0) {
    console.log(`\n${C.red}${C.bold}VERDICT: TEST SUITE FAILED (${failedTests} failures)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`\n${C.green}${C.bold}VERDICT: ALL 10 TESTS PASSED (100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  }
}

main().catch((err) => {
  console.error('\nFatal test runner error:', err);
  if (serverChildProcess) serverChildProcess.kill('SIGTERM');
  process.exit(1);
});

